273	          Object part = parts.next();
274	          if (part != null) {
275	            appendable.append(Joiner.this.toString(part));
276	            break;
277	          }
278	        }
279	        while (parts.hasNext()) {
280	          Object part = parts.next();
281	          if (part != null) {
282	            appendable.append(separator);
283	            appendable.append(Joiner.this.toString(part));
284	          }
285	        }
286	        return appendable;
287	      }
