522	  private static int expandedCapacity(int oldCapacity, int minCapacity) {
523	    if (minCapacity < 0) {
524	      throw new IllegalArgumentException("cannot store more than Integer.MAX_VALUE elements");
525	    } else if (minCapacity <= oldCapacity) {
526	      return oldCapacity;
527	    }
528	    // careful of overflow!
529	    int newCapacity = oldCapacity + (oldCapacity >> 1) + 1;
530	    if (newCapacity < minCapacity) {
531	      newCapacity = Integer.highestOneBit(minCapacity - 1) << 1;
532	    }
533	    if (newCapacity < 0) {
534	      newCapacity = Integer.MAX_VALUE;
535	      // guaranteed to be >= newCapacity
536	    }
537	    return newCapacity;
538	  }
