516	  private String joinList(List<?> parts) {
517	    /*
518	     * If we can quickly determine how many elements there are likely to be, then we can use the
519	     * fastest possible implementation, which delegates to the array overload of String.join.
520	     *
521	     * In theory, we can quickly determine the size of any Collection. However, thanks to
522	     * regrettable implementations like our own Sets.filter, Collection.size() is sometimes a
523	     * linear-time operation, and it can even have side effects. Thus, we limit the special case to
524	     * List, which is _even more likely_ to have size() implemented to be fast and side-effect-free.
525	     *
526	     * We could consider recognizing specific other collections as safe (like ImmutableCollection,
527	     * except ContiguousSet!) or as not worth this optimization (CopyOnWriteArrayList?).
528	     */
529	    int size = parts.size();
530	    if (size == 0) {
531	      return "";
532	    }
533	    CharSequence[] toJoin = new CharSequence[size];
534	    int i = 0;
535	    for (Object part : parts) {
536	      if (i == toJoin.length) {
537	        /*
538	         * We first initialized toJoin to the size of the input collection. However, that size can
539	         * go out of date (for a collection like CopyOnWriteArrayList, which may have been safely
540	         * modified concurrently), or it might have been only an estimate to begin with (for a
541	         * collection like ConcurrentHashMap, which sums up several counters that may not be in
542	         * sync with one another). We accommodate that by resizing as necessary.
543	         */
544	        toJoin = Arrays.copyOf(toJoin, expandedCapacity(toJoin.length, toJoin.length + 1));
545	      }
546	      toJoin[i++] = toString(part);
547	    }
548	    // We might not have seen the expected number of elements, as discussed above.
549	    if (i != toJoin.length) {
550	      toJoin = Arrays.copyOf(toJoin, i);
551	    }
552	    return String.join(separator, toJoin);
553	  }
